$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((git rev-parse --show-toplevel).Trim());$scriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;$zip=Get-ChildItem -LiteralPath $scriptDir -Filter 'CPF_DOCUMENTATION_V1_2_5_FINAL_OVERLAY_*.zip'|Sort-Object LastWriteTime -Descending|Select-Object -First 1;if(!$zip){throw 'OVERLAY ZIP NOT FOUND'};$zip=$zip.FullName;$shaFile=Join-Path $scriptDir 'CPF_DOCUMENTATION_V1_2_5_FINAL_OVERLAY.sha256';if(!(Test-Path $shaFile)){throw 'SHA FILE NOT FOUND'};$expected=((Get-Content $shaFile -Raw).Trim().Split()[0]).ToUpperInvariant();$actual=(Get-FileHash -Algorithm SHA256 -LiteralPath $zip).Hash.ToUpperInvariant();if($actual-ne$expected){throw "ZIP SHA256 MISMATCH expected=$expected actual=$actual"};$tmp=Join-Path $env:TEMP ('cpf-doc-v125-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $tmp|Out-Null;try{Expand-Archive -LiteralPath $zip -DestinationPath $tmp -Force;$m=Join-Path $tmp 'cpf-docs\deliverables\documentation\DELETE_MANIFEST.txt';Get-Content -LiteralPath $m|ForEach-Object{$s=$_.Trim();if($s-and-not$s.StartsWith('#')){if([IO.Path]::IsPathRooted($s)-or$s.Contains('..')-or[Management.Automation.WildcardPattern]::ContainsWildcardCharacters($s)){throw "UNSAFE DELETE PATH: $s"};$p=[IO.Path]::GetFullPath((Join-Path $root $s.Replace('/','\')));if(!$p.StartsWith($root.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw "OUTSIDE ROOT: $s => $p"};if(Test-Path -LiteralPath $p){$i=Get-Item -LiteralPath $p -Force;if($i.PSIsContainer){throw "FILE MANIFEST CONTAINS DIRECTORY: $s"};Remove-Item -LiteralPath $p -Force}}};$d=Join-Path $tmp 'cpf-docs\deliverables\documentation\DELETE_EMPTY_DIRS.txt';Get-Content -LiteralPath $d|ForEach-Object{$s=$_.Trim();if($s-and-not$s.StartsWith('#')){$p=[IO.Path]::GetFullPath((Join-Path $root $s.Replace('/','\')));if($p.StartsWith($root.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)-and(Test-Path $p)-and@(Get-ChildItem -LiteralPath $p -Force).Count-eq0){Remove-Item -LiteralPath $p -Force}}};Get-ChildItem -LiteralPath $tmp -Force|ForEach-Object{Copy-Item -LiteralPath $_.FullName -Destination $root -Recurse -Force};python .\cpf-docs\governance\documentation-harness\validators\validate_harness.py;if($LASTEXITCODE-ne0){throw 'HARNESS VALIDATION FAILED'};python .\cpf-docs\governance\documentation-harness\validators\validate_readme.py;if($LASTEXITCODE-ne0){throw 'README VALIDATION FAILED'};python .\cpf-docs\deliverables\documentation\verify_documentation_delivery.py;if($LASTEXITCODE-ne0){throw 'DOCUMENTATION VALIDATION FAILED'};Write-Host '[CPF][DOC] V1.2.5 DELETE + APPLY + VERIFY PASS'}finally{Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue}